(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],names={'安排采购':'purchase','生成采购需求':'request','智能补货':'replenish','齐套计算':'kit','删除':'delete'};
window.ENHANCED_BOM_CONTEXT=()=>{try{const text=localStorage.getItem('blacklake-enhanced-workbench-v33');if(text===null)return{versionId:'DEMO-BOM-V1',revision:0,signature:'initial'};const state=JSON.parse(text),v=state.versions?.find(v=>v.id===state.activeVersion);if(!v||state.schema!==33||state.factoryId!=='DEMO-FACTORY')return{invalid:true};return{versionId:v.id,revision:state.revision,signature:JSON.stringify({id:v.id,quantity:v.quantity,lines:v.lines})};}catch{return{invalid:true};}};
window.ENHANCED_BOM_SCOPE=detail=>{const c=window.ENHANCED_BOM_CONTEXT();return detail==='DEMO-0001'&&c.versionId&&c.versionId!=='DEMO-BOM-V1'?detail+'@'+c.versionId:detail;};
const productMap={'DEMO-BOM-A1':'DEMO-FINISHED-A','DEMO-BOM-A2':'DEMO-SEMI-A','DEMO-BOM-A3':'DEMO-RAW-A','DEMO-BOM-A4':'DEMO-PACK-A'};
const map={'DEMO-BOM-A1':'line-root','DEMO-BOM-A2':'line-semi','DEMO-BOM-A3':'line-raw','DEMO-BOM-A4':'line-pack'};
window.ENHANCED_WORKBENCH_OPEN=(name)=>{const rows=$$('[data-v28-bom-node]').filter(r=>$('input[type=checkbox]',r)?.checked);if(!rows.length){window.DEMO_CONTEXT?.toast('请先选择本地BOM行');return;}if(rows.some(r=>r.dataset.v28Detail!=='DEMO-0001'||!map[r.dataset.v28BomNode])){window.DEMO_CONTEXT?.toast('增强工作台当前仅配置DEMO-0001样本，未将其他明细猜配到该样本');return;}const headers=$$('.kodo-art-table-thead .kodo-art-table-row>.kodo-art-table-cell').map(e=>e.textContent.trim()),quantityIndex=headers.indexOf('计划缺料数'),hints={};for(const row of rows){const fields=window.DEMO_V30_BOM_FIELDS?.(row.dataset.v28Detail,row.dataset.v28BomNode)||{};if(fields['产品ID']&&fields['产品ID']!==productMap[row.dataset.v28BomNode]){window.DEMO_CONTEXT?.toast('产品已替换，尚无增强产品ID映射，未按名称猜配');return;}const value=Number(String(row.children[quantityIndex]?.textContent||'').replace(/,/g,''));if(quantityIndex<0||!Number.isFinite(value)||value<0||value>1e12){window.DEMO_CONTEXT?.toast('计划缺料数量无法核对，未打开业务动作');return;}hints[map[row.dataset.v28BomNode]]=value;}const ids=rows.map(r=>map[r.dataset.v28BomNode]),context=window.ENHANCED_BOM_CONTEXT();if(context.invalid){window.DEMO_CONTEXT?.toast('增强工作台数据无效，未打开业务动作');return;}location.href='D-V33-enhanced-workbench.html?tab=business&action='+names[name]+'&lines='+encodeURIComponent(ids.join(','))+'&expectedVersion='+encodeURIComponent(context.versionId)+'&expectedRevision='+context.revision+'&sourceQuantities='+encodeURIComponent(JSON.stringify(hints));};
function wire(){const p=window.DEMO_PAGE?.id;let parent,tab;if(p==='BL-02-03'){parent=$('.kodo-art-table-toolbar-right');tab='business';$$('[data-v30-action]').forEach(b=>{if(names[b.dataset.v30Action]){b.disabled=false;b.title='原型增强：进入本地业务预览，不调用源站';}});}else if(p==='BL-09-02'){parent=$('.kodo-art-table-toolbar-right');tab='bom';}else if(location.pathname.endsWith('/D-V24-print-designer.html')){const b=$$('button').find(b=>b.textContent.replace(/\s/g,'')==='保存');parent=b?.parentElement?.parentElement;tab='sheets';}if(!parent||$('[data-enhanced-entry]',parent))return;const a=document.createElement('a');a.dataset.enhancedEntry='';a.href='D-V33-enhanced-workbench.html?tab='+tab;a.textContent='增强工作台';a.title='原型增强：高级表格、BOM版本和本地批量业务';a.className='kodo-new-btn kodo-new-btn-default';a.style.cssText='display:inline-flex;align-items:center;justify-content:center;margin-left:8px;white-space:nowrap;padding:4px 12px;border:1px solid #00b578;border-radius:4px;color:#009e72;background:#fff;font-size:14px;height:32px';parent.append(a);}
window.addEventListener('storage',e=>{if(e.key==='blacklake-enhanced-workbench-v33')window.dispatchEvent(new Event('v30-bom-render'));});
document.addEventListener('DOMContentLoaded',()=>{wire();new MutationObserver(wire).observe(document.body,{subtree:true,childList:true});});
})();
